const KEY = 'bookshelf:favorites';

let slugs = $state<string[]>([]);

export const favorites = {
	/** Reads saved favorites; call once mounted in the browser so hydration matches the server. */
	load(): void {
		try {
			const value: unknown = JSON.parse(localStorage.getItem(KEY) ?? '[]');
			slugs = Array.isArray(value) ? value.filter((slug) => typeof slug === 'string') : [];
		} catch {
			slugs = [];
		}
	},
	has(slug: string): boolean {
		return slugs.includes(slug);
	},
	toggle(slug: string): void {
		slugs = slugs.includes(slug) ? slugs.filter((s) => s !== slug) : [...slugs, slug];
		localStorage.setItem(KEY, JSON.stringify(slugs));
	}
};
