<script lang="ts">
	import { enhance } from '$app/forms';
	import { readContact, validateContact, type ContactErrors } from '#lib/contact.js';
	import type { PageProps } from './$types';

	let { form }: PageProps = $props();

	// Errors found in the browser; cleared once a valid form is sent.
	let clientErrors = $state<ContactErrors | null>(null);

	const errors = $derived<ContactErrors>(
		clientErrors ?? (form && 'errors' in form ? form.errors : {})
	);
	const values = $derived(form && 'values' in form ? form.values : undefined);
	const sentName = $derived(!clientErrors && form && 'success' in form ? form.name : null);
</script>

