	<title>Contact | Bookshelf</title>
</svelte:head>

<h1>Contact</h1>

{#if sentName !== null}
	<p role="status">Thanks, {sentName}! Your message has been sent.</p>
{/if}

<form
	method="POST"
	novalidate
	use:enhance={({ formData, cancel }) => {
		const found = validateContact(readContact(formData));
		if (Object.keys(found).length > 0) {
			clientErrors = found;
			cancel();
			return;
		}
		clientErrors = null;
	}}
